1	import * as THREE from "three";
2	import { EnvSetup } from "../../app/EnvSetup.js";
3	import { SceneObject } from "../../core/SceneObject.js";
4	import type {
5	  GravityBallsObjectOptions,
6	  GravityBallsTweenProps,
7	} from "../../types/object.types.js";
8	import { Helpers } from "../../utils/Helpers.js";
9	
10	interface BallInfo {
11	  color: string;
12	  radius: number;
13	  radiusStart: number;
14	  radiusDeincrement: number;
15	  startX: number;
16	  startY: number;
17	  startZ: number;
18	  isXNegative: number;
19	  isZNegative: number;
20	  vx: number;
21	  vxMult: number;
22	  vy: number;
23	  vyMult: number;
24	  vz: number;
25	  vzMult: number;
26	  ID: number;
27	  bounced: boolean;
28	  startGravity: number;
29	  gravity: number;
30	  sphere: THREE.Mesh<THREE.CircleGeometry, THREE.MeshBasicMaterial>;
31	}
32	
33	export class GravityBalls extends SceneObject<GravityBallsTweenProps> {
34	  private static readonly COLORS: ReadonlyArray<string> = [
35	    "#bada55",
36	    "#bada55",
37	    "#bada55",
38	    "bada55",
39	  ];
40	  private static readonly RADIUS = 3;
41	  private static readonly DOTS_PER_INTERVAL = 5;
42	  private static readonly SPAWN_INTERVAL_SEC = 0.015;
43	  private static readonly FLOOR_LEVEL = -100;
44	  private static readonly FLOOR_DIMENSIONS = 1500;
45	  /** Original gravity-balls coordinate system (~1500 unit floor) shrunk to fit rocket scale. */
46	  private static readonly INNER_SCALE_DEFAULT = 0.05;
47	  /** `?debug=1` 모드에서 점·플로어가 인터랙션·인트로에 가려지지 않게 키우는 배수. */
48	  private static readonly INNER_SCALE_DEBUG = 0.2;
49	  private static readonly DEBUG_RENDER_ORDER = 9999;
50	  private static readonly DEBUG_FLOOR_COLOR = "#ff00ff";
51	
52	  private readonly _isDebug = EnvSetup.hasQueryFlag("debug", "1");
53	
54	  private _options: Partial<GravityBallsObjectOptions> = {};
55	  private _built = false;
56	  private _innerGroup: THREE.Group | null = null;
57	  private _floor: THREE.Mesh<THREE.BoxGeometry, THREE.MeshLambertMaterial> | null =
58	    null;
59	  private _spheresInfo = new Map<number, BallInfo>();
60	  private _sphereIndex = 0;
61	  private _canvasMouse = new THREE.Vector3(0, 0, 0);
62	  private _spawnAccumulator = 0;
63	
64	  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
65	    if (props != null) this._options = { ...this._options, ...props };
66	    return this;
67	  }
68	
69	  override getAnimationTarget(): THREE.Object3D | null {
70	    return this.getTimelineRoot();
71	  }
72	
73	  override getTweenApplyMode(): "mergeAndSync" {
74	    return "mergeAndSync";
75	  }
76	
77	  protected override getOptions(): Record<string, unknown> {
78	    return this._options as Record<string, unknown>;
79	  }
80	
81	  protected override applyVisibility(visible: boolean): void {
82	    const root = this.getTimelineRoot();
83	    if (!root) return;
84	    root.visible = visible;
85	    if (!visible) this._clearAllSpheres();
86	  }
87	
88	  override runObject(): void {
89	    const ctx = this._context;
90	    if (!ctx?.scene) return;
91	
92	    const root = this.ensureTimelineRoot("gravityBallsRoot");
93	    if (!root) return;
94	
95	    const attachTo = this._options.attachTo;
96	    const offset = this._options.offset ?? { x: 0, y: 0, z: 0 };
97	    const p = this._options.position ?? { x: 0, y: 0, z: 0 };
98	    const r = this._options.rotation ?? { x: 0, y: 0, z: 0 };
99	    const s = this._options.scale ?? { x: 1, y: 1, z: 1 };
100	
101	    if (attachTo && typeof ctx.getObject === "function") {
102	      const target = ctx.getObject(attachTo);
103	      if (target instanceof THREE.Object3D) {
104	        target.add(root);
105	        root.position.set(offset.x ?? 0, offset.y ?? 0, offset.z ?? 0);
106	      } else {
107	        root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
108	      }
109	    } else {
110	      root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
111	    }
112	
113	    Helpers.applyRotationDeg(root, r);
114	    root.scale.set(s.x ?? 1, s.y ?? 1, s.z ?? 1);
115	
116	    const inner = new THREE.Group();
117	    inner.name = "gravityBallsInner";
118	    const innerScale = this._isDebug
119	      ? GravityBalls.INNER_SCALE_DEBUG
120	      : GravityBalls.INNER_SCALE_DEFAULT;
121	    inner.scale.setScalar(innerScale);
122	    root.add(inner);
123	    this._innerGroup = inner;
124	
125	    this._buildFloor();
126	    this._built = true;
127	  }
128	
129	  override runUpdate(deltaTime: number): void {
130	    if (!this._built) return;
131	    const root = this.getTimelineRoot();
132	    if (!root) return;
133	    if (this._isDebug && !root.visible) root.visible = true;
134	    if (!root.visible) return;
135	
136	    this._spawnAccumulator += deltaTime;
137	    while (this._spawnAccumulator >= GravityBalls.SPAWN_INTERVAL_SEC) {
138	      for (let i = 0; i < GravityBalls.DOTS_PER_INTERVAL; i += 1) {
139	        this._initDot();
140	      }
141	      this._spawnAccumulator -= GravityBalls.SPAWN_INTERVAL_SEC;
142	    }
143	
144	    for (const info of Array.from(this._spheresInfo.values())) {
145	      this._drawDot(info);
146	    }
147	  }
148	
149	  override dispose(): void {
150	    this._clearAllSpheres();
151	    if (this._floor) {
152	      this._floor.geometry.dispose();
153	      this._floor.material.dispose();
154	      this._floor.parent?.remove(this._floor);
155	      this._floor = null;
156	    }
157	    if (this._innerGroup) {
158	      this._innerGroup.parent?.remove(this._innerGroup);
159	      this._innerGroup = null;
160	    }
161	    this._built = false;
162	    super.dispose();
163	  }
164	
165	  private _buildFloor(): void {
166	    const inner = this._innerGroup;
167	    if (!inner) return;
168	    const geometry = new THREE.BoxGeometry(
169	      GravityBalls.FLOOR_DIMENSIONS,
170	      3,
171	      GravityBalls.FLOOR_DIMENSIONS,
172	    );
173	    const material = new THREE.MeshLambertMaterial({
174	      color: this._isDebug ? GravityBalls.DEBUG_FLOOR_COLOR : "#000000",
175	      wireframe: this._isDebug,
176	    });
177	    material.depthWrite = false;
178	    material.transparent = true;
179	    material.opacity = this._isDebug ? 0.6 : 0.2;
180	    const floor = new THREE.Mesh(geometry, material);
181	    floor.position.y = GravityBalls.FLOOR_LEVEL - GravityBalls.RADIUS / 2;
182	    floor.position.z = 0;
183	    if (this._isDebug) floor.renderOrder = GravityBalls.DEBUG_RENDER_ORDER;
184	    inner.add(floor);
185	    this._floor = floor;
186	  }
187	
188	  private _initDot(): void {
189	    const inner = this._innerGroup;
190	    if (!inner) return;
191	    const radius = GravityBalls.RADIUS;
192	    const colorIdx = this._random(0, 4);
193	    const color = GravityBalls.COLORS[colorIdx] ?? "#bada55";
194	    const radiusStart = radius;
195	    const radiusDeincrement = radius * -0.002;
196	    const startX = this._canvasMouse.x || 0;
197	    let startY = this._canvasMouse.y || 100;
198	    const startZ = this._canvasMouse.z || 0;
199	    if (startY < GravityBalls.FLOOR_LEVEL - radiusStart / 2) {
200	      startY = GravityBalls.FLOOR_LEVEL - radiusStart / 2;
201	    }
202	    const isXNegative = this._random(1, 2);
203	    const isZNegative = this._random(1, 2);
204	    const vx =
205	      isXNegative === 1
206	        ? this._random(0, 50) * -0.15
207	        : this._random(0, 50) * 0.15;
208	    const vxMult = this._random(10, 20) * 0.15;
209	    const vy = this._random(-10, 20);
210	    const vyMult = this._random(4, 6) * -0.1;
211	    const vz =
212	      isZNegative === 1
213	        ? this._random(-25, 25) * -0.4
214	        : this._random(-25, 25) * 0.4;
215	    const vzMult = this._random(10, 20) * 0.1;
216	    this._sphereIndex += 1;
217	    const ID = this._sphereIndex;
218	    const startGravity = 10;
219	    const geometry = new THREE.CircleGeometry(radius, 20);
220	    const material = new THREE.MeshBasicMaterial({
221	      color,
222	      side: THREE.DoubleSide,
223	    });
224	    if (this._isDebug) {
225	      material.depthTest = false;
226	      material.depthWrite = false;
227	      material.transparent = true;
228	    }
229	    const sphere = new THREE.Mesh(geometry, material);
230	    if (this._isDebug) sphere.renderOrder = GravityBalls.DEBUG_RENDER_ORDER;
231	    inner.add(sphere);
232	
233	    this._spheresInfo.set(ID, {
234	      color,
235	      radius,
236	      radiusStart,
237	      radiusDeincrement,
238	      startX,
239	      startY,
240	      startZ,
241	      isXNegative,
242	      isZNegative,
243	      vx,
244	      vxMult,
245	      vy,
246	      vyMult,
247	      vz,
248	      vzMult,
249	      ID,
250	      bounced: false,
251	      startGravity,
252	      gravity: startGravity,
253	      sphere,
254	    });
255	  }
256	
257	  private _drawDot(info: BallInfo): void {
258	    info.sphere.scale.x += info.radiusDeincrement;
259	    info.sphere.scale.y += info.radiusDeincrement;
260	    info.sphere.scale.z += info.radiusDeincrement;
261	    info.startX += info.vx * 0.6;
262	    info.startY -= info.vy * 0.5;
263	    info.startZ -= info.vz * 0.6;
264	    info.sphere.position.x = info.startX;
265	    info.sphere.position.y = info.startY;
266	    info.sphere.position.z = info.startZ;
267	
268	    if (
269	      info.sphere.position.y <
270	      GravityBalls.FLOOR_LEVEL - info.radiusStart / 2
271	    ) {
272	      if (!info.bounced) {
273	        info.vx *= info.vxMult;
274	        info.vz *= info.vzMult;
275	      } else {
276	        info.vx *= 0.95;
277	        info.vz *= 0.95;
278	      }
279	      const half = GravityBalls.FLOOR_DIMENSIONS / 2;
280	      const outsideFloor =
281	        info.sphere.position.x > half ||
282	        info.sphere.position.x < -half ||
283	        info.sphere.position.z > half ||
284	        info.sphere.position.z < -half;
285	      if (!outsideFloor) {
286	        info.vy *= info.vyMult;
287	        info.sphere.position.y =
288	          GravityBalls.FLOOR_LEVEL + info.radiusStart * info.sphere.scale.x;
289	      } else {
290	        info.gravity = info.startGravity / 4;
291	        info.startY -= info.vy * 0.01;
292	        info.sphere.position.y =
293	          info.startY + (20 - info.radiusStart * info.sphere.scale.x);
294	      }
295	      info.bounced = true;
296	    }
297	
298	    info.vy += info.gravity;
299	
300	    if (info.sphere.scale.y <= 0.1) {
301	      this._spheresInfo.delete(info.ID);
302	      info.sphere.parent?.remove(info.sphere);
303	      info.sphere.geometry.dispose();
304	      info.sphere.material.dispose();
305	    }
306	  }
307	
308	  private _clearAllSpheres(): void {
309	    for (const info of this._spheresInfo.values()) {
310	      info.sphere.parent?.remove(info.sphere);
311	      info.sphere.geometry.dispose();
312	      info.sphere.material.dispose();
313	    }
314	    this._spheresInfo.clear();
315	  }
316	
317	  private _random(min: number, max: number): number {
318	    return Math.floor(Math.random() * max) + min;
319	  }
320	}
