49	function createSetOptionsSpec(
50	  id: keyof ObjectOptionsByKey,
51	  create: () => SceneObject,
52	): ObjectRegistrationSpec {
53	  return {
54	    id,
55	    create,
56	    applyOptions: (instance, options) => {
57	      const target = instance as { setOptions?: (props: unknown) => unknown };
58	      if (typeof target.setOptions === "function") {
59	        target.setOptions(options);
60	      }
61	    },
62	  };
63	}
64	
65	function createDefaultRegistry(): ObjectFactoryRegistry {
66	  return {
67	    [rocket]: createSetOptionsSpec(rocket, () => new Rocket()),
68	    [jetEngine]: createSetOptionsSpec(jetEngine, () => new JetEngine()),
69	    [gravityBalls]: createSetOptionsSpec(gravityBalls, () => new GravityBalls()),
70	    [mainBackground]: createSetOptionsSpec(
71	      mainBackground,
72	      () => new Background(mainBackground),
73	    ),
74	    [aboutBackground]: createSetOptionsSpec(
75	      aboutBackground,
76	      () => new Background(aboutBackground),
77	    ),
78	    [cloud]: createSetOptionsSpec(
79	      cloud,
80	      () => new CloudPlane(),
81	    ),
82	    [cloud2]: createSetOptionsSpec(
83	      cloud2,
84	      () => new CloudPlane(),
85	    ),
86	    [cloud3]: createSetOptionsSpec(
87	      cloud3,
88	      () => new CloudPlane(),
89	    ),
90	    [cloud4]: createSetOptionsSpec(
91	      cloud4,
92	      () => new CloudPlane(),
93	    ),
94	    [cloud5]: createSetOptionsSpec(
95	      cloud5,
96	      () => new CloudPlane(),
97	    ),
98	    [cloud6]: createSetOptionsSpec(
99	      cloud6,
100	      () => new CloudPlane(),
101	    ),
102	    [ground]: createSetOptionsSpec(ground, () => new Ground()),
103	    [planet]: createSetOptionsSpec(planet, () => new Planet()),
104	    [sceneLights]: {
105	      id: sceneLights,
106	      create: () => new Light(),
107	      applyOptions: (instance, options) => {
108	        const target = instance as {
109	          setOptions?: (
110	            props: Partial<SceneLightsObjectOptions> | undefined,
111	          ) => unknown;
112	        };
113	        target.setOptions?.(
114	          options as Partial<SceneLightsObjectOptions> | undefined,
115	        );
116	      },
117	    },
118	    [earth]: createSetOptionsSpec(earth, () => new Earth()),
119	    [astronaut]: createSetOptionsSpec(astronaut, () => new Astronaut()),
120	    [sceneTransitionVeil]: createSetOptionsSpec(
121	      sceneTransitionVeil,
122	      () => new TransitionVeil(),
123	    ),
124	    [terrian]: createSetOptionsSpec(terrian, () => new AboutTerrian()),
125	    [windowObj]: createSetOptionsSpec(windowObj, () => new Window()),
126	  };
